fn hook(item:&str,components:&mut serde_json::Map<String,serde_json::Value>){if item=="arcadiandream:hisou_sword"{let seconds=if crate::loot::arcadian_settings::config()["hisouSwordOptions"]["canDisableShields"].as_bool().unwrap_or(true){5.0}else{0.0};components.insert("minecraft:weapon".into(),serde_json::json!({"item_damage_per_attack":1,"disable_blocking_for_seconds":seconds}));}}
